mapper.select:
select * from ( SELECT distinct T1.ENTRUST_ID entrustId ,T1.ENTRUST_STATUS entrustStatus ,case when T2.TARGET_TYPE = '01' then ROUND(T4.ORDER_FINISH_AMT/T1.ENTRUST_NUM,4) else ROUND(T4.ORDER_FINISH_AMT/T2.ENTRUST_AMT_TARGET,4) end as implementPercent ,case when T2.TARGET_TYPE = '01' then ROUND(T4.ENT_FINISH_AMT/T1.ENTRUST_NUM,4) else ROUND(T4.ENT_FINISH_AMT/T2.ENTRUST_AMT_TARGET,4) end as dealPercent ,T5.PORTFOLIO_ID portfolioId ,T5.PORTFOLIO_NAME portfolioName ,T1.FINPROD_ID finprodId ,T7.FINPROD_NAME finprodName ,T7.FINPROD_MARKET_ID finprodMarketId ,T1.FINPROD_TYPE2 finprodType2 ,T1.TRADE_MARKET tradeMarket ,T1.PS ps ,T1.PRICE_MODEL priceModel ,T1.PRICE price ,T1.ENTRUST_AMT entrustAmt ,T1.ENTRUST_NUM entrustNum ,T1.VDATE vdate ,T1.MDATE mdate ,T2.TARGET_TYPE targetType ,T2.TRADER trader ,T2.HK_MARKET hkseMarket ,T2.ENTRUST_AMT_TARGET entrustAmtHk ,T2.SEC_ACCT_ID secAcctId ,nvl(T5.PARENT_PORTFOLIO_ID, T1.PORTFOLIO_ID) parentPortfolioId FROM ETR_ENTRUST T1 INNER JOIN ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID and T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID where T1.TRADE_MARKET = #{TRADE_PLACE_06}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_DATE = TO_DATE(#{sysDate},'yyyy-mm-dd')
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_DATE >=TO_DATE(#{startDate},'yyyy-mm-dd')
AND T1.ENTRUST_DATE <=TO_DATE(#{endDate},'yyyy-mm-dd')
union all SELECT distinct T1.ENTRUST_ID entrustId ,T1.ENTRUST_STATUS entrustStatus ,ROUND(nvl(T4.ORDER_FINISH_AMT,0)/nvl(T1.ENTRUST_NUM,T1.ENTRUST_AMT),4) as implementPercent ,ROUND(nvl(T4.ENT_FINISH_AMT,0)/nvl(T1.ENTRUST_NUM,T1.ENTRUST_AMT),4) as dealPercent ,T5.PORTFOLIO_ID portfolioId ,T5.PORTFOLIO_NAME portfolioName ,T1.FINPROD_ID finprodId ,T7.FINPROD_NAME finprodName ,T7.FINPROD_MARKET_ID finprodMarketId ,T1.FINPROD_TYPE2 finprodType2 ,T1.TRADE_MARKET tradeMarket ,T1.PS ps ,T1.PRICE_MODEL priceModel ,T1.PRICE price ,T1.ENTRUST_AMT entrustAmt ,T1.ENTRUST_NUM entrustNum ,T1.VDATE vdate ,T1.MDATE mdate ,T2.TARGET_TYPE targetTYpe ,T2.TRADER trader ,T2.HK_MARKET hkseMarket ,T2.ENTRUST_AMT_TARGET entrustAmtHk ,T2.SEC_ACCT_ID secAcctId ,nvl(T5.PARENT_PORTFOLIO_ID, T1.PORTFOLIO_ID) parentPortfolioId FROM WFL_ETR_ENTRUST T1 INNER JOIN WFL_ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID and T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID where T1.TRADE_MARKET = #{TRADE_PLACE_06}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_DATE = TO_DATE(#{sysDate},'yyyy-mm-dd')
AND T1.ENTRUST_DATE >=TO_DATE(#{startDate},'yyyy-mm-dd')
AND T1.ENTRUST_DATE <=TO_DATE(#{endDate},'yyyy-mm-dd')
) temp

SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR AS finprodName, FP_ADD.SH_OR_ZH AS hkseMarket, TEMP.AMOUNT AS positionsNum, ESP.AMOUNT AS sellNum, MSP.PRE_CLOSE_PRICE AS price, CASE WHEN (nvl(T2.SHARE_AMT,0)+PSP.AMOUNT)=0 THEN nvl(PSV.DSC_COST_AMT,0)+nvl(T1.TRADE_AMT,0) ELSE ((nvl(PSV.DSC_COST_AMT,0)+nvl(T1.TRADE_AMT,0)) - (nvl(T2.SHARE_AMT,0)*(nvl(PSV.DSC_COST_AMT,0)+nvl(T1.TRADE_AMT,0))/(nvl(T2.SHARE_AMT,0)+PSP.AMOUNT))) END AS positionsAmt, PSP.AMOUNT AS ptlPositionsNum, FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, SSAI.TRD_ACCT_ID AS acctNo, nvl(PP.PARENT_PORTFOLIO_ID,PSP.PORTFOLIO_ID) AS parentPortfolioId, atd.COST_POSITION, atd.COST_POSITION_NUM FROM ( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , nvl(PP.PARENT_PORTFOLIO_ID, PSP.PORTFOLIO_ID) AS PARENT_PORTFOLIO_ID, PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.BRANCH AS BRANCH, SUM(CASE WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_03}) THEN nvl(PSP.AMOUNT,0) ELSE -1* nvl(PSP.AMOUNT,0) END) AS AMOUNT FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_03}) AND PSP.CDATE = #{sysDate} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PP.PARENT_PORTFOLIO_ID, PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.BRANCH )TEMP LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE, SUM(T.AMOUNT) AMOUNT FROM ETR_SEC_POSITION T GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE ) ESP ON TEMP.PORTFOLIO_ID = ESP.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = ESP.SEC_ACCT_ID AND TEMP.FINPROD_ID = ESP.FINPROD_ID AND TEMP.BRANCH = ESP.BRANCH AND TEMP.CDATE = ESP.CDATE LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FP_ADD ON TEMP.FINPROD_ID = FP_ADD.FINPROD_ID
LEFT JOIN MST_SHARE_PRICE MSP ON FP.FINPROD_MARKET_ID = MSP.SHARES_ID AND MSP.DEAL_DATE <= #{sysDate} LEFT JOIN (SELECT MAX(M.DEAL_DATE) DEAL_DATE ,SHARES_ID FROM MST_SHARE_PRICE M WHERE M.DEAL_DATE <= #{sysDate} group by M.SHARES_ID) MSP2 on MSP.SHARES_ID = MSP2.SHARES_ID and MSP.DEAL_DATE = MSP2.DEAL_DATE LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.CDATE, SUM(T.DSC_COST_AMT) DSC_COST_AMT FROM PTL_SEC_VALUTION T WHERE T.CDATE = #{sysDate} - 1 GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.CDATE ) PSV ON TEMP.PORTFOLIO_ID = PSV.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = PSV.SEC_ACCT_ID AND TEMP.FINPROD_ID = PSV.FINPROD_ID AND PSV.CDATE = #{sysDate} - 1 LEFT JOIN ( SELECT TPD.FINPROD_ID, TPD.SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID, SUM(nvl(TPD.TRADE_AMT,0)) AS TRADE_AMT, SUM(nvl(TPD.SHARE_AMT,0)) AS SHARE_AMT FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID WHERE ( ( TPD.PS IN ( #{PS_T01}, #{PS_T46}, #{PS_T97}, #{PS_T04}) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F10}) ) ) AND TPD.CHL_ID IS NULL AND TPD.TRADE_DATE = #{sysDate} GROUP BY TPD.FINPROD_ID, TPD.SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID ) T1 ON TEMP.PORTFOLIO_ID = T1.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = T1.SEC_MANAGE_ACCT_ID AND TEMP.FINPROD_ID = T1.FINPROD_ID LEFT JOIN ( SELECT TPD.FINPROD_ID AS FINPROD_ID , TPD.SEC_MANAGE_ACCT_ID AS SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID AS PORTFOLIO_ID, SUM(nvl(TPD.SHARE_AMT,0)) AS SHARE_AMT FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID WHERE TPD.PS IN ( #{PS_T02}, #{PS_T03}, #{PS_T19} ) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10}) AND TPD.CHL_ID IS NULL AND TPD.TRADE_DATE = #{sysDate} GROUP BY TPD.FINPROD_ID , TPD.SEC_MANAGE_ACCT_ID , TPDA.PORTFOLIO_ID ) T2 ON TEMP.PORTFOLIO_ID = T2.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = T2.SEC_MANAGE_ACCT_ID AND TEMP.FINPROD_ID= T2.FINPROD_ID LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE, SUM(T.AMOUNT) AMOUNT FROM PTL_SEC_POSITION T WHERE T.BRANCH=0 AND T.HODING_TYPE IN (#{POSITION_TYPE_03}) AND T.CDATE = #{sysDate} GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE ) PSP ON TEMP.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = PSP.SEC_ACCT_ID AND TEMP.FINPROD_ID = PSP.FINPROD_ID AND TEMP.BRANCH = PSP.BRANCH AND TEMP.CDATE = PSP.CDATE LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID LEFT JOIN COST_POSITION_DB atd on atd.portfolio_id = TEMP.portfolio_id and atd.finprod_id = TEMP.finprod_id and atd.CDATE = #{sysDate} - 1 WHERE FP.TRADE_MARKET = #{TRADE_PLACE_06}
#{portfolioId,jdbcType=VARCHAR}
AND SSAI.TRADE_PLACE = #{tradePlace,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
AND TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
